// The only hand-written code in this workflow. Everything else uses n8n's
// built-in nodes so the logic stays visible/inspectable without reading code.
//
// WHY this step exists: Meta's Conversions API requires email/phone/name to
// arrive as lowercase, trimmed, SHA-256 hashes - never plain text. Hashing
// happens here, once, right after the lead lands, so no raw PII travels
// further than it has to. This is also the last point where the raw request
// headers (for client_ip_address) are still available, before the item gets
// reshaped down to just the body fields.
const crypto = require('crypto');

const body = $json.body ?? $json;
const headers = $json.headers ?? {};

const email = (body.contact?.email || '').toLowerCase().trim();
const phone = (body.contact?.phone || '').replace(/[^0-9]/g, '');

const fullName = (body.contact?.name || '').trim().toLowerCase();
const [firstName = '', ...rest] = fullName.split(/\s+/);
const lastName = rest.join(' ');

// Prefer a real upstream-proxy IP header over x-forwarded-for's leftmost
// (client) entry, since x-forwarded-for can be spoofed by the client itself
// if no trusted proxy strips/overwrites it first.
const clientIp =
  headers['cf-connecting-ip'] ||
  headers['x-real-ip'] ||
  (headers['x-forwarded-for'] || '').split(',')[0].trim() ||
  undefined;

return {
  ...body,
  hashedEmail: crypto.createHash('sha256').update(email).digest('hex'),
  hashedPhone: crypto.createHash('sha256').update(phone).digest('hex'),
  hashedFirstName: firstName ? crypto.createHash('sha256').update(firstName).digest('hex') : undefined,
  hashedLastName: lastName ? crypto.createHash('sha256').update(lastName).digest('hex') : undefined,
  clientIp,
};
